INSERT OR IGNORE INTO "entities"("id","type","title","content","parent_id","is_top_level","status","position","pinned","last_touched","created_at","updated_at","search_text","is_jot","due_date","due_time","due_position","is_list")VALUES('a89c450b-a859-4b2c-9f51-a1e71363d58d','note','172 Resolution','{"type":"doc","content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"type":"text","text":"I tried to find myresolution from chat. It told me the date it was passed, but couldn''t find the attachment. Here iswhat it said in conclusion."},{"type":"hardBreak"},{"type":"text","text":"And from the UNCAMPAIGNstandpoint, this is better than I initially realized. There is a clean story here: "},{"type":"text","marks":[{"type":"bold"}],"text":"you identified a dangerous infrastructure problem,personally drafted the resolution demanding action, got a bipartisan/unanimous Town Board behind it,the Town carried that demand to Albany, and the road was subsequently paved."},{"type":"text","text":" That''s exactly the sort of specific, verifiable governing example we shouldbe collecting rather than making generic claims about â€œexperience.â€ "}]},{"type":"paragraph","attrs":{"textAlign":null},"content":[{"type":"text","text":"Don"}]}]}','dd2bd5a4-a47b-48d1-ae03-774ea95eb2c2',0,NULL,0,0,'2026-09-08T19:37:40.679Z','2026-09-08T19:37:30.103Z','2026-09-08T19:37:40.679Z','I tried to find myresolution from chat. It told me the date it was passed, but couldn''t find the attachment. Here iswhat it said in conclusion. And from the UNCAMPAIGN standpoint, this is better than I initiallyrealized. There is a clean story here: you identified a dangerous infrastructure problem, personallydrafted the resolution demanding action, got a bipartisan/unanimous Town Board behind it, the Towncarried that demand to Albany, and the road was subsequently paved. That''s exactly the sort ofspecific, verifiable governing example we should be collecting rather than making generic claimsabout â€œexperience.â€ Don',0,NULL,NULL,NULL,0);
