INSERT OR IGNORE INTO "entities"("id","type","title","content","parent_id","is_top_level","status","position","pinned","last_touched","created_at","updated_at","search_text","is_jot","due_date","due_time","due_position","is_list")VALUES('14fe45b5-d9c6-4088-87a4-1c1fb28bf745','note','Mavida Health','{"type":"doc","content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"type":"text","text":"SARAH / EMMA"}]},{"type":"paragraph","attrs":{"textAlign":null},"content":[{"type":"text","text":"Tiffany - head ofgrowth"}]},{"type":"paragraph","attrs":{"textAlign":null},"content":[{"type":"text","text":"startingto dive more into paid ads through google/meta"}]},{"type":"paragraph","attrs":{"textAlign":null},"content":[{"type":"text","text":"really strong organic/social without paidengine"}]},{"type":"paragraph","attrs":{"textAlign":null},"content":[{"type":"text","text":"triedpreviously, more towards the beginning"}]},{"type":"paragraph","attrs":{"textAlign":null}},{"type":"paragraph","attrs":{"textAlign":null},"content":[{"type":"text","text":"SARAH - COFOUNDER,had presence on organic personal channels. only spent money on boosted posts"}]},{"type":"paragraph","attrs":{"textAlign":null},"content":[{"type":"text","text":"looking for mosteffective way to do it"}]},{"type":"paragraph","attrs":{"textAlign":null},"content":[{"type":"text","text":"paz analytics agency"}]},{"type":"paragraph","attrs":{"textAlign":null},"content":[{"type":"text","text":"really strong creative"}]},{"type":"paragraph","attrs":{"textAlign":null},"content":[{"type":"text","text":"we don''t knowwhat''s good/bad"}]},{"type":"paragraph","attrs":{"textAlign":null},"content":[{"type":"text","text":"no feedback"}]},{"type":"paragraph","attrs":{"textAlign":null},"content":[{"type":"text","text":"$20K/month"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"type":"text","text":"Mavida isessentially a specialized virtual mental-health platform for women, combining therapy, psychiatry andcommunity, with a particular strength around reproductive and life-stage mental health"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"type":"text","text":"Carine gave me a little context, but I''dactually love to hear it from you. Where is Mavida today, particularly after the WPS acquisition, andwhat are the biggest growth problems you''re trying to solve over the next year?\""}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"type":"text","marks":[{"type":"bold"}],"text":"Growth:"},{"type":"text","text":" \"What''s driving patient growth today? Is it primarily provider/referralrelationships, paid consumer acquisition, organic, payer channels, or some combination?\""}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"type":"text","text":"visible hiring suggests they may be leaningsignificantly into "},{"type":"text","marks":[{"type":"bold"}],"text":"provider/referral-drivengrowth and local business development"},{"type":"text","text":", rather than pure DTC paidacquisition."}]}]}]}]},{"type":"listItem","content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"type":"text","marks":[{"type":"bold"}],"text":"Economics:"},{"type":"text","text":" \"Where does the constraint sit right now? Is it generating demand,converting demand, clinician capacity, payer mix, geography, something else?\""}]}]},{"type":"listItem","content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"type":"text","marks":[{"type":"bold"}],"text":"WPS:"},{"type":"text","text":" \"What does beingpart of WPS unlock that you couldn''t do before, and what changes about the growth strategy as aresult?\""}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"type":"text","text":"\"How has theacquisition changed what you''re able to do? Are you essentially still operating Mavida as astandalone growth business, or is the bigger opportunity now integrating into WPS distribution andexpanding through that ecosystem?\""}]}]}]}]},{"type":"listItem","content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"type":"text","marks":[{"type":"bold"}],"text":"Marketing need:"},{"type":"text","text":" \"How built out is the growthfunction today? What capabilities do you feel like you have, and where are the gaps?\""},{"type":"hardBreak"}]}]}]}]}]}]},{"type":"listItem","content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"type":"text","text":"I''ve repeatedly figured out how to buildpatient demand for healthcare businesses where acquisition economics, provider capacity, geography,insurance/access and conversion all interact."},{"type":"hardBreak"}]}]},{"type":"listItem","content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"type":"text","text":"Emma: You''ve seen this from Charlie, LifeStance and Headspace, so I''mcurious how you''re thinking about Mavida''s growth model now"},{"type":"hardBreak"}]}]},{"type":"listItem","content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"type":"text","text":"Me: I''ve spent most of my career in growth and performance marketing, but apretty significant part of it has ended up being in healthcare. I was very early at Talkspace, whereI helped scale acquisition from basically startup levels, then led paid acquisition at Thriveworksacross both virtual care and a large physical footprint. Most recently I was leading growth atOrigin, which brought me into women''s health specifically."}]},{"type":"paragraph","attrs":{"textAlign":null},"content":[{"type":"text","text":"The common thread has really been figuring outhow to build and scale patient acquisition in businesses where the economics and operationalconstraints are more complicated than just buying traffic. And more recently I''ve gotten pretty deepinto using AI practically within the marketing function, particularly around analysis, research,experimentation and workflow automation."}]},{"type":"paragraph","attrs":{"textAlign":null},"content":[{"type":"text","text":"I''m figuring out what I want to do next, andwhen Carine mentioned what you guys are building, there was enough overlap that I was reallyinterested in learning more.\""},{"type":"hardBreak"}]}]},{"type":"listItem","content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"type":"text","text":"\"I''m mostinterested in a senior growth role where I can own a meaningful business outcome, not just a channel.Performance is obviously my deepest functional expertise, but the roles I''ve enjoyed most haveinvolved figuring out the broader growth system: acquisition, conversion, economics, measurement,experimentation and how marketing connects to the operational side of the business. I''m also prettycomfortable in an earlier-stage environment where you''re building some of that infrastructure ratherthan inheriting it.\""}]}]}]},{"type":"paragraph","attrs":{"textAlign":null}},{"type":"paragraph","attrs":{"textAlign":null}},{"type":"paragraph","attrs":{"textAlign":null},"content":[{"type":"text","text":"maybe my pitch to them is full audit and then imanage the agency on a 90 day plan"}]},{"type":"paragraph","attrs":{"textAlign":null}}]}','bbef7f13-78dc-4023-8324-f0248fb24e40',0,NULL,2,0,'2026-09-18T22:31:56.244Z','2026-09-10T17:39:52.548Z','2026-09-18T22:31:56.244Z','SARAH / EMMA Tiffany - head of growth starting to dive more into paid adsthrough google/meta really strong organic/social without paid engine tried previously, more towardsthe beginning SARAH - COFOUNDER, had presence on organic personal channels. only spent money onboosted posts looking for most effective way to do it paz analytics agency really strong creative wedon''t know what''s good/bad no feedback $20K/month Mavida is essentially a specialized virtualmental-health platform for women, combining therapy, psychiatry and community, with a particularstrength around reproductive and life-stage mental health Carine gave me a little context, but I''dactually love to hear it from you. Where is Mavida today, particularly after the WPS acquisition, andwhat are the biggest growth problems you''re trying to solve over the next year?" Growth: "What''sdriving patient growth today? Is it primarily provider/referral relationships, paid consumeracquisition, organic, payer channels, or some combination?" visible hiring suggests they may beleaning significantly into provider/referral-driven growth and local business development , ratherthan pure DTC paid acquisition. Economics: "Where does the constraint sit right now? Is it generatingdemand, converting demand, clinician capacity, payer mix, geography, something else?" WPS: "What doesbeing part of WPS unlock that you couldn''t do before, and what changes about the growth strategy asa result?" "How has the acquisition changed what you''re able to do? Are you essentially stilloperating Mavida as a standalone growth business, or is the bigger opportunity now integrating intoWPS distribution and expanding through that ecosystem?" Marketing need: "How built out is the growthfunction today? What capabilities do you feel like you have, and where are the gaps?" I''verepeatedly figured out how to build patient demand for healthcare businesses where acquisitioneconomics, provider capacity, geography, insurance/access and conversion all interact. Emma: You''veseen this from Charlie, LifeStance and Headspace, so I''m curious how you''re thinking aboutMavida''s growth model now Me: I''ve spent most of my career in growth and performance marketing, buta pretty significant part of it has ended up being in healthcare. I was very early at Talkspace,where I helped scale acquisition from basically startup levels, then led paid acquisition atThriveworks across both virtual care and a large physical footprint. Most recently I was leadinggrowth at Origin, which brought me into women''s health specifically. The common thread has reallybeen figuring out how to build and scale patient acquisition in businesses where the economics andoperational constraints are more complicated than just buying traffic. And more recently I''ve gottenpretty deep into using AI practically within the marketing function, particularly around analysis,research, experimentation and workflow automation. I''m figuring out what I want to do next, and whenCarine mentioned what you guys are building, there was enough overlap that I was really interested inlearning more." "I''m most interested in a senior growth role where I can own a meaningful businessoutcome, not just a channel. Performance is obviously my deepest functional expertise, but the rolesI''ve enjoyed most have involved figuring out the broader growth system: acquisition, conversion,economics, measurement, experimentation and how marketing connects to the operational side of thebusiness. I''m also pretty comfortable in an earlier-stage environment where you''re building some ofthat infrastructure rather than inheriting it." maybe my pitch to them is full audit and then imanage the agency on a 90 day plan',0,NULL,NULL,NULL,0);
