INSERT OR IGNORE INTO "entities"("id","type","title","content","parent_id","is_top_level","status","position","pinned","last_touched","created_at","updated_at","search_text","is_jot","due_date","due_time","due_position","is_list")VALUES('77008182-4304-459f-befe-33ea7eda4931','note','Birches Health, VP ofMarketing','{"type":"doc","content":[{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"type":"text","text":"Elliott Rapaport -Founder & CEO"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"type":"text","text":"Founded in 2023after seeing a friend struggle to find appropriate gambling-addiction treatment"}]}]},{"type":"listItem","content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"type":"text","text":"Lack of high-quality, specialized virtual treatment that insurance wouldcover"}]}]},{"type":"listItem","content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"type":"text","text":"ACCESS PROBLEM - akin to TS"}]}]}]}]}]},{"type":"paragraph","attrs":{"textAlign":null}},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"type":"text","text":"Raised $20M acrossSeed and Series A, including a $10M Series A led by AlleyCorp"}]}]},{"type":"listItem","content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"type":"text","text":"Built out anational network, is in-network with 100+ insurance plans, and has treated thousands ofpatients"}]}]},{"type":"listItem","content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"type":"text","text":"Strong accessibility & outcome claims"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"type":"text","text":"nationally covered by insurance (2/3 of US POP)and 85% showed clinically significant improvement in gambling-disorder symptoms"},{"type":"hardBreak"}]}]}]}]},{"type":"listItem","content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"type":"text","text":"How do we turn a validated care model into amuch larger, predictable consumer acquisition machine?"}]}]}]},{"type":"paragraph","attrs":{"textAlign":null}},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"type":"text","text":"Experience"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"type":"text","text":"The reason I was so interested after talking tothe recruiter is that there are some pretty striking parallels between Birches and what I did atTalkspace. I joined Talkspace as employee number six and the first marketing hire, when virtualbehavioral health was still a very new category. I essentially built acquisition from scratch. Forthe first year I was doing most of it myself, and then built a team as we scaled."}]}]},{"type":"listItem","content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"type":"text","text":"I owned the full acquisition journey, with search as a major component, butreally everything from audience and messaging through landing pages, conversion, remarketing andretention. We scaled media from about $20,000 a month to more than $1 million a month, and what weoptimized toward changed as the company matured. Sometimes the mandate was growth, sometimes CACefficiency, and increasingly LTV:CAC."}]}]},{"type":"listItem","content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"type":"text","text":"What really caughtmy attention about Birches is that you''re solving a different clinical problem, but many of thegrowth questions feel very familiar: virtual behavioral health, a category consumers don''tnecessarily understand yet, high-intent search demand, insurance increasingly removing theaffordability barrier, and a need to build the growth function while still being very hands-on.That''s the kind of environment where I''ve done some of my best work."},{"type":"hardBreak"}]}]}]}]},{"type":"listItem","content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"type":"text","text":"Growth Problem"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"type":"text","text":"Capture existing intent - Birches needs to ownlow-funnel search terms with high intent (SEM & SEO/AEO/GEO) - gambling addiction help, sportsbetting addiction treatment"}]}]},{"type":"listItem","content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"type":"text","text":"Latent Demand - symptoms, consequences,questions (am I addicted to sports betting, how do I stop gambling)"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"type":"text","text":"FREE ASSESSMENT"}]}]}]}]},{"type":"listItem","content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"type":"text","text":"Post-Click"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"type":"text","text":"Spend>Visitor>Lead/Assessment>Contact>BV>Appointment Booked>AppointedAttended>Patient>Retained Patient"}]}]}]}]},{"type":"listItem","content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"type":"text","text":"Economics"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"type":"text","text":"Sub $300 CAC"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"type":"text","text":"By channel, by condition, payer, geography, contribution/LTV"}]}]},{"type":"listItem","content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"type":"text","text":"How do you define CAC and where does that target come from"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"type":"text","text":"Booked appt? Attended appt? activatedpatient?"}]}]},{"type":"listItem","content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"type":"text","text":"$300 an economic threshold based on contributionmargin and retention"},{"type":"hardBreak"}]}]}]}]}]}]}]}]}]}]},{"type":"listItem","content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"type":"text","text":"First 30 Days"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"type":"text","text":"Understand>IdentifyConstraints>Prioritize>Scale"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"type":"text","text":"Understand channeleconomics and the funnel at granular level"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"type":"text","text":"Search structure, query mix, CAC by campaign, landing-page CvR, lead>apptCvR, payer mix, geo, capacity constraints, CRM data, attribution, SEO footprint"}]}]}]}]}]}]}]}]},{"type":"listItem","content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"type":"text","text":"Days 30-60"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"type":"text","text":"Identify whereincremental dollars actually produce incremental patients, fix obvious funnel leakage and measurementproblems, establish experimentation roadmap across search, LPs, intake and messaging"}]}]}]}]},{"type":"listItem","content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"type":"text","text":"Days 60-90"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"type":"text","text":"Begin reallocatingcapital toward the highest marginal-return opportunities and establish the operating cadence forscaling"}]}]},{"type":"listItem","content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"type":"text","text":"BEFORE I TELL YOU I CAN SCALE SPEND, I WANT TO UNDERSTAND WHAT ACTUALLYCONSTRAINS SCALE"},{"type":"hardBreak"}]}]}]}]},{"type":"listItem","content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"type":"text","text":"Origin"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"type":"text","text":"â€œMy role was eliminated in August. Originwasn''t hitting the growth and financial goals the company had set, and they made some organizationalchanges as a result. Obviously, being the person responsible for growth, I understand that raises aquestion about my part in that. There were a number of things affecting the business beyondmarketing, including the economics and capacity constraints of scaling a clinical business, but Ialso don''t want to pretend marketing operates in a vacuum. I learned quite a bit from it."}]},{"type":"paragraph","attrs":{"textAlign":null},"content":[{"type":"text","text":"What I feel goodabout is the work I did there. I came in and owned the full patient acquisition engine across paid,organic, lifecycle and CRO, and got very deep into how you allocate marketing dollars when you''rebalancing CAC and LTV against actual clinical capacity. In some ways, that''s made me even moreinterested in Birches because it''s another healthcare business where marketing can''t just generateleads. You have to understand the economics and operational constraints all the way through to thepatient.â€ "}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"type":"text","text":"â€œYou should holdthe growth leader accountable for the things they can influence, and I wouldn''t ask you not to. Icertainly look back at things I could have done differently or pushed on earlier. But I also thinkone of the lessons from Origin is that in healthcare, growth isn''t synonymous with generating moredemand. You can generate patients that look efficient at the top of the funnel and still have pooreconomics once you account for conversion, LTV, payer mix and clinical capacity. I came away fromthat experience much more rigorous about understanding the entire system before deciding what growthactually means.â€ "}]}]}]}]}]}]}]},{"type":"paragraph","attrs":{"textAlign":null}},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"type":"text","text":"Questions"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"type":"text","marks":[{"type":"bold"}],"text":"What''s the biggest thing preventing you fromgrowing consumer acquisition faster today?"}]}]},{"type":"listItem","content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"type":"text","marks":[{"type":"bold"}],"text":"When you say CAC below $300 - how are you defining the acquired customerand how did you arrive at that threshold"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"type":"text","text":"When you talk about a sub-$300 CAC target, what''s the actual conversionevent you''re using for CAC"}]}]},{"type":"listItem","content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"type":"text","marks":[{"type":"bold"}],"text":"We''ve talked aboutthe sub-$300 CAC target. What''s on the other side of that equation? What does patient LTV look liketoday, and how confident are you in that number?"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"type":"text","marks":[{"type":"bold"}],"text":"What''s driving LTV today? Is it primarily numberof sessions, reimbursement rate, payer mix, treatment completion, or some combination?"}]}]}]}]},{"type":"listItem","content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"type":"text","marks":[{"type":"bold"}],"text":"Do you feel like retention and LTV are where youwant them to be clinically and economically, or is improving the back end of the funnel part of thegrowth opportunity too?"}]}]},{"type":"listItem","content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"type":"text","marks":[{"type":"bold"}],"text":"Are you seeingmaterially different unit economics by acquisition source? For example, does a patient acquiredthrough high-intent search behave differently from someone coming through a sportsbook partnership,organic, referral or another source?"}]}]},{"type":"listItem","content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"type":"text","marks":[{"type":"bold"}],"text":"What about by patientsegment? Are you seeing meaningful differences in conversion, treatment duration or LTV by condition,payer, geography or other characteristics?"}]}]},{"type":"listItem","content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"type":"text","marks":[{"type":"bold"}],"text":"How sophisticated do you think you''ve gotten today in understanding whichpatients you actually want more of? Not just who can we acquire below $300, but which conditions,payers, geographies, channels or patient profiles ultimately produce the best clinical outcomes andeconomics?"}]}]}]}]},{"type":"listItem","content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"type":"text","marks":[{"type":"bold"}],"text":"Where does the funnelbreak down today? Is the bigger opportunity generating more demand, converting the demand you''realready getting, or improving what happens between lead and first appointment"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"type":"text","text":"BOTH - CRO, TOP OF FUNNEL NOT LARGEENOUGH"}]}]}]}]},{"type":"listItem","content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"type":"text","text":"How much headroom do you believe there is inpaid search today before you start seeing meaningful marginal CAC degradation?"}]}]},{"type":"listItem","content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"type":"text","marks":[{"type":"bold"}],"text":"How do payer mix and provider capacity factor intowhere you actually want marketing to generate demand?"}]}]},{"type":"listItem","content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"type":"text","marks":[{"type":"bold"}],"text":"When you think about Birches three years from now, do you see gamblingremaining the core of the company, or is the larger vision to become the category leader acrossbehavioral addictions?"}]}]},{"type":"listItem","content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"type":"text","marks":[{"type":"bold"}],"text":"I spent some timelooking at the competitive landscape, and one thing that jumped out at me was Kindbridge. They''vedone a good job building distribution relationships with DraftKings, FanDuel and BetMGM. You''veobviously built relationships on that side as well. How do you think about Kindbridge? Do you seethem primarily as a clinical competitor, a distribution competitor, or both?"}]}]},{"type":"listItem","content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"type":"text","marks":[{"type":"bold"}],"text":"Talk to me about how you think about partnershipsand business development as part of the overall growth model. How important do you expect thatchannel to be relative to D2C over the next couple of years?"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"type":"text","marks":[{"type":"bold"}],"text":"Do you think of relationships with sportsbooksprimarily as patient acquisition channels, brand/credibility partnerships, or something broader?"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"type":"text","text":"I noticed Kindbridge has built relationshipswith DraftKings, FanDuel and BetMGM. How do you think about that competitive dynamic?"}]}]},{"type":"listItem","content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"type":"text","marks":[{"type":"bold"}],"text":"What is Penn doing for you today?"}]}]}]}]}]}]},{"type":"listItem","content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"type":"text","marks":[{"type":"bold"}],"text":"Do you have a sense for who actually initiates thejourney today? Is it usually the patient themselves, or do you see a meaningful amount coming fromspouses, parents, friends or other family members?"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"type":"text","marks":[{"type":"bold"}],"text":"Do you have a specific experience today for someonewho''s worried about somebody else? I could imagine â€˜I think my husband has a gambling problemâ€™being a very different search intent and funnel than â€˜I need help with gambling."}]}]}]}]},{"type":"listItem","content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"type":"text","text":"How much experimentation have you done on the post-click experience so far?Have you built dedicated landing pages by intent or audience, or is most paid traffic going into arelatively common experience today?"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"type":"text","text":"What are you usingto build landing pages? How quickly can the team actually launch a new page or test?"}]}]},{"type":"listItem","content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"type":"text","marks":[{"type":"bold"}],"text":"Do you feel like you''ve learned much yet aboutwhich messages actually move conversion: insurance coverage, privacy, specialization, outcomes,immediacy of getting help, something else?"}]}]}]}]},{"type":"listItem","content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"type":"text","text":"How are youhandling creative today? Is that capability internal, agency/freelance, or some combination?"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"type":"text","text":"How much creative testing are you doing today,and do you feel like creative production is keeping pace with what you''d ideally want totest?"}]}]}]}]},{"type":"listItem","content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"type":"text","marks":[{"type":"bold"}],"text":"I''m really interestedin the free assessment. How important is that experience to acquisition today? Are people actuallyfinding and completing it at meaningful volume?"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"type":"text","text":"ADDED TAHT RECENTLY, CLEANER READ ON IT TODAY"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"type":"text","text":"What does the funnel look like after someonecompletes it? How many ultimately become an appointment and then an actual patient?"}]}]},{"type":"listItem","content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"type":"text","marks":[{"type":"bold"}],"text":"Do you think of the assessment primarily as aconversion tool for people who already know they have a problem, or as a way of helping someonerecognize that they may need treatment?"}]}]}]}]}]}]},{"type":"listItem","content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"type":"text","marks":[{"type":"bold"}],"text":"How confident are you today that you know where an incremental patient camefrom and what it actually cost to acquire them?"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"type":"text","text":"How are you connecting media and lead-source data through appointment bookingand ultimately into becoming a patient? Where do you feel like you lose visibility today?"}]}]}]}]},{"type":"listItem","content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"type":"text","marks":[{"type":"bold"}],"text":"What role does the CRM play today after someoneraises their hand? Is it primarily operational, or are you actively using it for lead nurturing,segmentation and re-engagement?"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"type":"text","marks":[{"type":"bold"}],"text":"What happens today to someone who completes an assessment or submits theirinformation but doesn''t book? Is there a structured nurture journey"}]}]},{"type":"listItem","content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"type":"text","marks":[{"type":"bold"}],"text":"How sophisticated is the segmentation? For example,can you treat someone differently based on condition, insurance status, geography, acquisition sourceor where they dropped out of the funnel?"}]}]}]}]},{"type":"listItem","content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"type":"text","marks":[{"type":"bold"}],"text":"How is organic search performing today? Is SEO already a meaningful sourceof patients, or do you see it as more of an underdeveloped opportunity?"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"type":"text","text":"How are you thinking about the balance betweenhigh-intent treatment searches and the much larger universe of informational searches around gamblingbehavior, gaming, social media, internet addiction and so forth?"}]}]}]}]},{"type":"listItem","content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"type":"text","marks":[{"type":"bold"}],"text":"How should I think about the supply side of theequation? If marketing really starts working and patient volume accelerates, where do clinicalcapacity constraints start showing up?"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"type":"text","marks":[{"type":"bold"}],"text":"How are clinicians structured today? W-2,independent contractors, or a mix? And how do you recruit and onboard additional clinical capacity asyou enter new markets or demand grows?"}]}]},{"type":"listItem","content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"type":"text","marks":[{"type":"bold"}],"text":"Do you ever have situations where marketing should actually be throttled orredirected because of clinician availability, payer mix or capacity?"}]}]}]}]},{"type":"listItem","content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"type":"text","marks":[{"type":"bold"}],"text":"I understand there was previously someone leadingmarketing. What did you learn from that experience, and what are you hoping will be different withthe person you bring in now?"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"type":"text","text":"Was the gap morearound strategy, execution, leadership, pace, performance, or just fit for the stage the company isin now?"}]}]}]}]},{"type":"listItem","content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"type":"text","marks":[{"type":"bold"}],"text":"Talk me through thetwo people currently on the marketing team. What do they own today, what are they particularly strongat, and where are you expecting this hire to fill gaps versus developing the existing team?"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"type":"text","text":"Are you expecting the VP to work within roughlythat team structure for the foreseeable future, or is there an expectation that I''ll build theorganization as we scale?"}]}]},{"type":"listItem","content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"type":"text","text":"What outside resources are already in place?Agencies, freelancers, creative, SEO, development, analytics"}]}]}]}]},{"type":"listItem","content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"type":"text","marks":[{"type":"bold"}],"text":"Could you walk me through the leadership team and where marketing sitswithin it? Who would I be working most closely with day-to-day?"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"type":"text","text":"How do growth, clinical, product/engineering and operations work togethertoday? Who owns the parts of the patient journey that marketing doesn''t directly control"}]}]}]}]},{"type":"listItem","content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"type":"text","marks":[{"type":"bold"}],"text":"Gambling is clearly the hero condition in the wayBirches is positioned today, but you also treat gaming, internet/social media, pornography and otherbehavioral addictions. How should I think about the relative importance of those other conditions tothe business today?"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"type":"text","marks":[{"type":"bold"}],"text":"Are those already meaningful contributors to patient volume and revenue, orare they still relatively nascent?"}]}]},{"type":"listItem","content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"type":"text","text":"Do you see gambling as the wedge thatestablishes Birches and then allows you to expand into adjacent behavioral addictions, or do youultimately expect gambling to remain the dominant category"}]}]},{"type":"listItem","content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"type":"text","marks":[{"type":"bold"}],"text":"From a marketing perspective, would you want this person actively buildingdemand across those other conditions now, or is the priority to win gambling first?"}]}]},{"type":"listItem","content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"type":"text","text":"Are you seeing meaningful differences in the acquisition dynamics bycondition? Search volume, CAC, conversion rate, insurance coverage, retention?"}]}]},{"type":"listItem","content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"type":"text","text":"How much overlap are you seeing between conditions? Are patients generallypresenting with one specific issue, or are you seeing enough comorbidity that there''s an opportunityto think about the patient and their needs more broadly than the initial condition that brought themin?"}]}]}]}]}]}]}]},{"type":"paragraph","attrs":{"textAlign":null}},{"type":"paragraph","attrs":{"textAlign":null}},{"type":"paragraph","attrs":{"textAlign":null}},{"type":"paragraph","attrs":{"textAlign":null},"content":[{"type":"text","text":"MOST BUDGETMichael.Palladino@TheOriginWay.comARDS GAMBLING - WANTS TO SCALE"}]},{"type":"paragraph","attrs":{"textAlign":null}},{"type":"paragraph","attrs":{"textAlign":null},"content":[{"type":"text","text":"CASE STUDY - 2-4 HOURS"}]},{"type":"paragraph","attrs":{"textAlign":null}},{"type":"paragraph","attrs":{"textAlign":null}},{"type":"paragraph","attrs":{"textAlign":null},"content":[{"type":"text","text":"3 sided marketplace"}]},{"type":"paragraph","attrs":{"textAlign":null},"content":[{"type":"text","text":"payer - scaledexponentially well, 200M covered lives (best in class)"}]},{"type":"paragraph","attrs":{"textAlign":null},"content":[{"type":"text","text":"provider side scaling nicely - 400ish providers(5%, majority 1099)"}]},{"type":"paragraph","attrs":{"textAlign":null},"content":[{"type":"text","text":"-demand constrained"}]},{"type":"paragraph","attrs":{"textAlign":null},"content":[{"type":"text","text":"-focused provider growth team"}]},{"type":"paragraph","attrs":{"textAlign":null},"content":[{"type":"text","text":"demand side - b- toa-"}]},{"type":"paragraph","attrs":{"textAlign":null},"content":[{"type":"text","text":"small team -growth leader, lcm, 2 content creators, wants to streamline, wants to own the team - be responsible,what team needs to look like 3-12"}]},{"type":"paragraph","attrs":{"textAlign":null},"content":[{"type":"text","text":"attribution - oursprivacy"}]},{"type":"paragraph","attrs":{"textAlign":null},"content":[{"type":"text","text":"about 45 people"}]},{"type":"paragraph","attrs":{"textAlign":null},"content":[{"type":"text","text":"clinical owner - grow therapy"}]},{"type":"paragraph","attrs":{"textAlign":null},"content":[{"type":"text","text":"network - payerfacing "}]},{"type":"paragraph","attrs":{"textAlign":null},"content":[{"type":"text","text":"owners -2 opeators"}]},{"type":"paragraph","attrs":{"textAlign":null},"content":[{"type":"text","text":"marketing"}]},{"type":"paragraph","attrs":{"textAlign":null},"content":[{"type":"text","text":"product/tech - vp of engine"}]},{"type":"paragraph","attrs":{"textAlign":null},"content":[{"type":"text","text":"growth product / care delivery "}]},{"type":"paragraph","attrs":{"textAlign":null},"content":[{"type":"text","text":"conversionpercentage"}]},{"type":"paragraph","attrs":{"textAlign":null},"content":[{"type":"text","text":"lifecycle marketing owner "}]},{"type":"paragraph","attrs":{"textAlign":null}},{"type":"horizontalRule"},{"type":"paragraph","attrs":{"textAlign":null}},{"type":"horizontalRule"},{"type":"paragraph","attrs":{"textAlign":null},"content":[{"type":"text","text":"RECRUITER"}]},{"type":"paragraph","attrs":{"textAlign":null},"content":[{"type":"text","text":"VP Marketing, Birches Health"}]},{"type":"paragraph","attrs":{"textAlign":null},"content":[{"type":"text","text":"Gino Calavitta"}]},{"type":"paragraph","attrs":{"textAlign":null},"content":[{"type":"text","text":"Series a startup, $20M in vc backed funding. Nonsubstance abuse â€“ gambling, gaming, internet, social media"}]},{"type":"paragraph","attrs":{"textAlign":null},"content":[{"type":"text","text":"Fully virtual â€“ insurance covered for 2/3 ofpopulation, all 50 states"}]},{"type":"paragraph","attrs":{"textAlign":null},"content":[{"type":"text","text":"Revenue doubled yoy"}]},{"type":"paragraph","attrs":{"textAlign":null},"content":[{"type":"text","text":"Mid 7 figure run rate"}]},{"type":"paragraph","attrs":{"textAlign":null},"content":[{"type":"text","text":"Vp of marketing â€“report to co/founder and own full stack acquisition â€“ lead to first appointment. Seeking customerswho need treatment. Not focused on provider/health insurance side"}]},{"type":"paragraph","attrs":{"textAlign":null},"content":[{"type":"text","text":"Optimize CAC across paid channel"}]},{"type":"paragraph","attrs":{"textAlign":null},"content":[{"type":"text","text":"Sem expertise, seoaspects"}]},{"type":"paragraph","attrs":{"textAlign":null},"content":[{"type":"text","text":"Directlymangae 2 folks"}]},{"type":"paragraph","attrs":{"textAlign":null},"content":[{"type":"text","text":"Blend of strategy and execution"}]},{"type":"paragraph","attrs":{"textAlign":null},"content":[{"type":"text","text":"Backfill â€“ parting ways with VP of marketing,came in as interim (b2b background)"}]},{"type":"paragraph","attrs":{"textAlign":null},"content":[{"type":"text","text":"$250-$1MM/month â€“ sub $300 CAC target"}]},{"type":"paragraph","attrs":{"textAlign":null},"content":[{"type":"text","text":"Strategic bets â€“ 10x acquisition,"}]},{"type":"paragraph","attrs":{"textAlign":null},"content":[{"type":"text","text":"Â "}]},{"type":"paragraph","attrs":{"textAlign":null},"content":[{"type":"text","text":"Current have head ofgrowth â€“ James Bowell?"}]},{"type":"paragraph","attrs":{"textAlign":null}},{"type":"horizontalRule"},{"type":"paragraph","attrs":{"textAlign":null},"content":[{"type":"text","text":"09/21/2026"}]},{"type":"paragraph","attrs":{"textAlign":null},"content":[{"type":"text","text":"Elliott"}]},{"type":"paragraph","attrs":{"textAlign":null},"content":[{"type":"text","text":"James - lead growth/product, product management arm, all thigns customer acq,website, referrals (anything before client attends first appt). under 2 years. started inside growth,hands on, experience in growth space"}]},{"type":"paragraph","attrs":{"textAlign":null},"content":[{"type":"text","text":"Quinn - lead finance & networking ops, 3.5+ years, providers in network withinsurance plans"}]},{"type":"paragraph","attrs":{"textAlign":null},"content":[{"type":"text","text":"Alec"}]},{"type":"paragraph","attrs":{"textAlign":null}},{"type":"paragraph","attrs":{"textAlign":null}},{"type":"paragraph","attrs":{"textAlign":null}},{"type":"paragraph","attrs":{"textAlign":null}},{"type":"paragraph","attrs":{"textAlign":null}},{"type":"paragraph","attrs":{"textAlign":null},"content":[{"type":"text","text":"30d conversionwindow on meta"}]},{"type":"paragraph","attrs":{"textAlign":null}},{"type":"paragraph","attrs":{"textAlign":null},"content":[{"type":"text","text":"are you driving people to get started"}]},{"type":"paragraph","attrs":{"textAlign":null}},{"type":"paragraph","attrs":{"textAlign":null}},{"type":"paragraph","attrs":{"textAlign":null}},{"type":"paragraph","attrs":{"textAlign":null}},{"type":"paragraph","attrs":{"textAlign":null}},{"type":"paragraph","attrs":{"textAlign":null}},{"type":"paragraph","attrs":{"textAlign":null},"content":[{"type":"text","text":"mainly paid"}]},{"type":"paragraph","attrs":{"textAlign":null}},{"type":"paragraph","attrs":{"textAlign":null},"content":[{"type":"text","text":"3 quiz tests - people experiencing gambling,sex, porn"}]},{"type":"paragraph","attrs":{"textAlign":null},"content":[{"type":"text","text":"google- quiz didn''t do well"}]},{"type":"paragraph","attrs":{"textAlign":null}},{"type":"paragraph","attrs":{"textAlign":null}},{"type":"paragraph","attrs":{"textAlign":null},"content":[{"type":"text","text":"andrew - strategy (BHT)"}]},{"type":"paragraph","attrs":{"textAlign":null}},{"type":"paragraph","attrs":{"textAlign":null}},{"type":"paragraph","attrs":{"textAlign":null}},{"type":"paragraph","attrs":{"textAlign":null}},{"type":"paragraph","attrs":{"textAlign":null}},{"type":"paragraph","attrs":{"textAlign":null}},{"type":"paragraph","attrs":{"textAlign":null}},{"type":"paragraph","attrs":{"textAlign":null}},{"type":"paragraph","attrs":{"textAlign":null}},{"type":"paragraph","attrs":{"textAlign":null}},{"type":"paragraph","attrs":{"textAlign":null}},{"type":"paragraph","attrs":{"textAlign":null}},{"type":"paragraph","attrs":{"textAlign":null}},{"type":"paragraph","attrs":{"textAlign":null}},{"type":"paragraph","attrs":{"textAlign":null}},{"type":"paragraph","attrs":{"textAlign":null}},{"type":"paragraph","attrs":{"textAlign":null}},{"type":"paragraph","attrs":{"textAlign":null}},{"type":"paragraph","attrs":{"textAlign":null}},{"type":"paragraph","attrs":{"textAlign":null}}]}','bbef7f13-78dc-4023-8324-f0248fb24e40',0,NULL,1,0,'2026-09-21T15:57:34.222Z','2026-09-16T01:02:32.789Z','2026-09-21T15:57:34.222Z','Elliott Rapaport - Founder &CEO Founded in 2023 after seeing a friend struggle to find appropriate gambling-addiction treatmentLack of high-quality, specialized virtual treatment that insurance would cover ACCESS PROBLEM - akinto TS Raised $20M across Seed and Series A, including a $10M Series A led by AlleyCorp Built out anational network, is in-network with 100+ insurance plans, and has treated thousands of patientsStrong accessibility & outcome claims nationally covered by insurance (2/3 of US POP) and 85% showedclinically significant improvement in gambling-disorder symptoms How do we turn a validated caremodel into a much larger, predictable consumer acquisition machine? Experience The reason I was sointerested after talking to the recruiter is that there are some pretty striking parallels betweenBirches and what I did at Talkspace. I joined Talkspace as employee number six and the firstmarketing hire, when virtual behavioral health was still a very new category. I essentially builtacquisition from scratch. For the first year I was doing most of it myself, and then built a team aswe scaled. I owned the full acquisition journey, with search as a major component, but reallyeverything from audience and messaging through landing pages, conversion, remarketing and retention.We scaled media from about $20,000 a month to more than $1 million a month, and what we optimizedtoward changed as the company matured. Sometimes the mandate was growth, sometimes CAC efficiency,and increasingly LTV:CAC. What really caught my attention about Birches is that you''re solving adifferent clinical problem, but many of the growth questions feel very familiar: virtual behavioralhealth, a category consumers don''t necessarily understand yet, high-intent search demand, insuranceincreasingly removing the affordability barrier, and a need to build the growth function while stillbeing very hands-on. That''s the kind of environment where I''ve done some of my best work. GrowthProblem Capture existing intent - Birches needs to own low-funnel search terms with high intent (SEM& SEO/AEO/GEO) - gambling addiction help, sports betting addiction treatment Latent Demand -symptoms, consequences, questions (am I addicted to sports betting, how do I stop gambling) FREEASSESSMENT Post-Click Spend>Visitor>Lead/Assessment>Contact>BV>Appointment Booked>AppointedAttended>Patient>Retained Patient Economics Sub $300 CAC By channel, by condition, payer, geography,contribution/LTV How do you define CAC and where does that target come from Booked appt? Attendedappt? activated patient? $300 an economic threshold based on contribution margin and retention First30 Days Understand>Identify Constraints>Prioritize>Scale Understand channel economics and the funnelat granular level Search structure, query mix, CAC by campaign, landing-page CvR, lead>appt CvR,payer mix, geo, capacity constraints, CRM data, attribution, SEO footprint Days 30-60 Identify whereincremental dollars actually produce incremental patients, fix obvious funnel leakage and measurementproblems, establish experimentation roadmap across search, LPs, intake and messaging Days 60-90 Beginreallocating capital toward the highest marginal-return opportunities and establish the operatingcadence for scaling BEFORE I TELL YOU I CAN SCALE SPEND, I WANT TO UNDERSTAND WHAT ACTUALLYCONSTRAINS SCALE Origin â€œMy role was eliminated in August. Origin wasn''t hitting the growth andfinancial goals the company had set, and they made some organizational changes as a result.Obviously, being the person responsible for growth, I understand that raises a question about my partin that. There were a number of things affecting the business beyond marketing, including theeconomics and capacity constraints of scaling a clinical business, but I also don''t want to pretendmarketing operates in a vacuum. I learned quite a bit from it. What I feel good about is the work Idid there. I came in and owned the full patient acquisition engine across paid, organic, lifecycleand CRO, and got very deep into how you allocate marketing dollars when you''re balancing CAC and LTVagainst actual clinical capacity. In some ways, that''s made me even more interested in Birchesbecause it''s another healthcare business where marketing can''t just generate leads. You have tounderstand the economics and operational constraints all the way through to the patient.â€ â€œYoushould hold the growth leader accountable for the things they can influence, and I wouldn''t ask younot to. I certainly look back at things I could have done differently or pushed on earlier. But Ialso think one of the lessons from Origin is that in healthcare, growth isn''t synonymous withgenerating more demand. You can generate patients that look efficient at the top of the funnel andstill have poor economics once you account for conversion, LTV, payer mix and clinical capacity. Icame away from that experience much more rigorous about understanding the entire system beforedeciding what growth actually means.â€ Questions What''s the biggest thing preventing you fromgrowing consumer acquisition faster today? When you say CAC below $300 - how are you defining theacquired customer and how did you arrive at that threshold When you talk about a sub-$300 CAC target,what''s the actual conversion event you''re using for CAC We''ve talked about the sub-$300 CACtarget. What''s on the other side of that equation? What does patient LTV look like today, and howconfident are you in that number? What''s driving LTV today? Is it primarily number of sessions,reimbursement rate, payer mix, treatment completion, or some combination? Do you feel like retentionand LTV are where you want them to be clinically and economically, or is improving the back end ofthe funnel part of the growth opportunity too? Are you seeing materially different unit economics byacquisition source? For example, does a patient acquired through high-intent search behavedifferently from someone coming through a sportsbook partnership, organic, referral or anothersource? What about by patient segment? Are you seeing meaningful differences in conversion, treatmentduration or LTV by condition, payer, geography or other characteristics? How sophisticated do youthink you''ve gotten today in understanding which patients you actually want more of? Not just whocan we acquire below $300, but which conditions, payers, geographies, channels or patient profilesultimately produce the best clinical outcomes and economics? Where does the funnel break down today?Is the bigger opportunity generating more demand, converting the demand you''re already getting, orimproving what happens between lead and first appointment BOTH - CRO, TOP OF FUNNEL NOT LARGE ENOUGHHow much headroom do you believe there is in paid search today before you start seeing meaningfulmarginal CAC degradation? How do payer mix and provider capacity factor into where you actually wantmarketing to generate demand? When you think about Birches three years from now, do you see gamblingremaining the core of the company, or is the larger vision to become the category leader acrossbehavioral addictions? I spent some time looking at the competitive landscape, and one thing thatjumped out at me was Kindbridge. They''ve done a good job building distribution relationships withDraftKings, FanDuel and BetMGM. You''ve obviously built relationships on that side as well. How doyou think about Kindbridge? Do you see them primarily as a clinical competitor, a distributioncompetitor, or both? Talk to me about how you think about partnerships and business development aspart of the overall growth model. How important do you expect that channel to be relative to D2C overthe next couple of years? Do you think of relationships with sportsbooks primarily as patientacquisition channels, brand/credibility partnerships, or something broader? I noticed Kindbridge hasbuilt relationships with DraftKings, FanDuel and BetMGM. How do you think about that competitivedynamic? What is Penn doing for you today? Do you have a sense for who actually initiates the journeytoday? Is it usually the patient themselves, or do you see a meaningful amount coming from spouses,parents, friends or other family members? Do you have a specific experience today for someone who''sworried about somebody else? I could imagine â€˜I think my husband has a gambling problemâ€™ being avery different search intent and funnel than â€˜I need help with gambling. How much experimentationhave you done on the post-click experience so far? Have you built dedicated landing pages by intentor audience, or is most paid traffic going into a relatively common experience today? What are youusing to build landing pages? How quickly can the team actually launch a new page or test? Do youfeel like you''ve learned much yet about which messages actually move conversion: insurance coverage,privacy, specialization, outcomes, immediacy of getting help, something else? How are you handlingcreative today? Is that capability internal, agency/freelance, or some combination? How much creativetesting are you doing today, and do you feel like creative production is keeping pace with whatyou''d ideally want to test? I''m really interested in the free assessment. How important is thatexperience to acquisition today? Are people actually finding and completing it at meaningful volume?ADDED TAHT RECENTLY, CLEANER READ ON IT TODAY What does the funnel look like after someone completesit? How many ultimately become an appointment and then an actual patient? Do you think of theassessment primarily as a conversion tool for people who already know they have a problem, or as away of helping someone recognize that they may need treatment? How confident are you today that youknow where an incremental patient came from and what it actually cost to acquire them? How are youconnecting media and lead-source data through appointment booking and ultimately into becoming apatient? Where do you feel like you lose visibility today? What role does the CRM play today aftersomeone raises their hand? Is it primarily operational, or are you actively using it for leadnurturing, segmentation and re-engagement? What happens today to someone who completes an assessmentor submits their information but doesn''t book? Is there a structured nurture journey Howsophisticated is the segmentation? For example, can you treat someone differently based on condition,insurance status, geography, acquisition source or where they dropped out of the funnel? How isorganic search performing today? Is SEO already a meaningful source of patients, or do you see it asmore of an underdeveloped opportunity? How are you thinking about the balance between high-intenttreatment searches and the much larger universe of informational searches around gambling behavior,gaming, social media, internet addiction and so forth? How should I think about the supply side ofthe equation? If marketing really starts working and patient volume accelerates, where do clinicalcapacity constraints start showing up? How are clinicians structured today? W-2, independentcontractors, or a mix? And how do you recruit and onboard additional clinical capacity as you enternew markets or demand grows? Do you ever have situations where marketing should actually be throttledor redirected because of clinician availability, payer mix or capacity? I understand there waspreviously someone leading marketing. What did you learn from that experience, and what are youhoping will be different with the person you bring in now? Was the gap more around strategy,execution, leadership, pace, performance, or just fit for the stage the company is in now? Talk methrough the two people currently on the marketing team. What do they own today, what are theyparticularly strong at, and where are you expecting this hire to fill gaps versus developing theexisting team? Are you expecting the VP to work within roughly that team structure for theforeseeable future, or is there an expectation that I''ll build the organization as we scale? Whatoutside resources are already in place? Agencies, freelancers, creative, SEO, development, analyticsCould you walk me through the leadership team and where marketing sits within it? Who would I beworking most closely with day-to-day? How do growth, clinical, product/engineering and operationswork together today? Who owns the parts of the patient journey that marketing doesn''t directlycontrol Gambling is clearly the hero condition in the way Birches is positioned today, but you alsotreat gaming, internet/social media, pornography and other behavioral addictions. How should I thinkabout the relative importance of those other conditions to the business today? Are those alreadymeaningful contributors to patient volume and revenue, or are they still relatively nascent? Do yousee gambling as the wedge that establishes Birches and then allows you to expand into adjacentbehavioral addictions, or do you ultimately expect gambling to remain the dominant category From amarketing perspective, would you want this person actively building demand across those otherconditions now, or is the priority to win gambling first? Are you seeing meaningful differences inthe acquisition dynamics by condition? Search volume, CAC, conversion rate, insurance coverage,retention? How much overlap are you seeing between conditions? Are patients generally presenting withone specific issue, or are you seeing enough comorbidity that there''s an opportunity to think aboutthe patient and their needs more broadly than the initial condition that brought them in? MOST BUDGETMichael.Palladino@TheOriginWay.comARDS GAMBLING - WANTS TO SCALE CASE STUDY - 2-4 HOURS 3 sidedmarketplace payer - scaled exponentially well, 200M covered lives (best in class) provider sidescaling nicely - 400ish providers (5%, majority 1099) -demand constrained -focused provider growthteam demand side - b- to a- small team - growth leader, lcm, 2 content creators, wants to streamline,wants to own the team - be responsible, what team needs to look like 3-12 attribution - oursprivacyabout 45 people clinical owner - grow therapy network - payer facing owners - 2 opeators marketingproduct/tech - vp of engine growth product / care delivery conversion percentage lifecycle marketingowner RECRUITER VP Marketing, Birches Health Gino Calavitta Series a startup, $20M in vc backedfunding. Non substance abuse â€“ gambling, gaming, internet, social media Fully virtual â€“ insurancecovered for 2/3 of population, all 50 states Revenue doubled yoy Mid 7 figure run rate Vp ofmarketing â€“ report to co/founder and own full stack acquisition â€“ lead to first appointment.Seeking customers who need treatment. Not focused on provider/health insurance side Optimize CACacross paid channel Sem expertise, seo aspects Directly mangae 2 folks Blend of strategy andexecution Backfill â€“ parting ways with VP of marketing, came in as interim (b2b background)$250-$1MM/month â€“ sub $300 CAC target Strategic bets â€“ 10x acquisition, Current have head ofgrowth â€“ James Bowell? 09/21/2026 Elliott James - lead growth/product, product management arm, allthigns customer acq, website, referrals (anything before client attends first appt). under 2 years.started inside growth, hands on, experience in growth space Quinn - lead finance & networking ops,3.5+ years, providers in network with insurance plans Alec 30d conversion window on meta are youdriving people to get started mainly paid 3 quiz tests - people experiencing gambling, sex, porngoogle - quiz didn''t do well andrew - strategy (BHT)',0,NULL,NULL,NULL,0);
