INSERT OR IGNORE INTO "entities"("id","type","title","content","parent_id","is_top_level","status","position","pinned","last_touched","created_at","updated_at","search_text","is_jot","due_date","due_time","due_position","is_list")VALUES('8fea41cd-387a-4588-93df-3bd1139cc25d','note','Doctronic','{"type":"doc","content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"type":"text","text":"Doctronic"}]},{"type":"paragraph","attrs":{"textAlign":null},"content":[{"type":"text","text":"They''re building anAI-first version of primary and urgent care. You start with an AI doctor for free, and if youactually need treatment, you''re handed off to a licensed physician who already has the context."}]},{"type":"paragraph","attrs":{"textAlign":null},"content":[{"type":"text","text":"$39 for self-pay"}]},{"type":"paragraph","attrs":{"textAlign":null},"content":[{"type":"text","text":"AI-assistedprescription renewals in Utah"}]},{"type":"paragraph","attrs":{"textAlign":null},"content":[{"type":"text","text":"Â "}]},{"type":"paragraph","attrs":{"textAlign":null},"content":[{"type":"text","text":"Health question â†’ AI conversation â†’ useful answer â†’ trust â†’account/history â†’ physician visit â†’ treatment â†’ repeat use â†’ ongoing primary-carerelationship"}]},{"type":"paragraph","attrs":{"textAlign":null},"content":[{"type":"text","text":"SoDoctronic has to design a very intelligent boundary between "},{"type":"text","marks":[{"type":"bold"}],"text":"free AI utility and monetizable human care"},{"type":"text","text":" whilemaintaining clinical safety and consumer trust."}]},{"type":"paragraph","attrs":{"textAlign":null},"content":[{"type":"text","text":"Â "}]},{"type":"paragraph","attrs":{"textAlign":null},"content":[{"type":"text","text":"\"Most of my career has been in consumer growthand performance marketing, but there''s been a pretty consistent thread of building acquisitionengines in businesses that are creating new consumer behaviors. I was employee six at Talkspace andhelped scale paid acquisition from about $20,000 a month to $1 million a month when online therapyitself was still a new concept. I later ran acquisition at Thriveworks across virtual care and morethan 300 physical locations, and most recently led growth at Origin across virtual and in-personwomen''s healthcare."}]},{"type":"paragraph","attrs":{"textAlign":null},"content":[{"type":"text","text":"The other piece that''s become increasingly important in how I work is AI.I''ve been building it into research, analysis, experimentation and marketing workflows prettyaggressively. So the combination of consumer healthcare, growth, and an AI-native product isobviously pretty interesting to me.\""}]},{"type":"paragraph","attrs":{"textAlign":null},"content":[{"type":"text","text":"Â "}]},{"type":"paragraph","attrs":{"textAlign":null},"content":[{"type":"text","text":"A consumer healthcare growth operator who knows how to take an emerginghealthcare behavior and turn it into a scalable acquisition and conversion engine."}]},{"type":"paragraph","attrs":{"textAlign":null},"content":[{"type":"text","marks":[{"type":"bold"}],"text":"Talkspace:"},{"type":"text","text":" Convince consumers that therapy canhappen online."}]},{"type":"paragraph","attrs":{"textAlign":null},"content":[{"type":"text","marks":[{"type":"bold"}],"text":"Thriveworks:"},{"type":"text","text":" Scale acquisition across physical +virtual behavioral healthcare."}]},{"type":"paragraph","attrs":{"textAlign":null},"content":[{"type":"text","marks":[{"type":"bold"}],"text":"Origin:"},{"type":"text","text":" Scale patientacquisition across physical + virtual women''s healthcare."}]},{"type":"paragraph","attrs":{"textAlign":null},"content":[{"type":"text","marks":[{"type":"bold"}],"text":"Doctronic:"},{"type":"text","text":" Convince consumers that the first interaction in healthcare can happen withAI."}]},{"type":"paragraph","attrs":{"textAlign":null},"content":[{"type":"text","text":"Â "}]},{"type":"paragraph","attrs":{"textAlign":null},"content":[{"type":"text","marks":[{"type":"bold"}],"text":"Questions I would ask them"}]},{"type":"orderedList","attrs":{"start":1,"type":"1"},"content":[{"type":"listItem","content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"type":"text","marks":[{"type":"bold"}],"text":"\"Where is thebusiness today in terms of growth? Is the bigger challenge acquiring more users, or converting theenormous amount of AI usage you already have into ongoing patient relationships?\""}]},{"type":"orderedList","attrs":{"start":1,"type":"1"},"content":[{"type":"listItem","content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"type":"text","marks":[{"type":"bold"}],"text":"AWARENESS IS LOW, A LOT OF MOMENTUM, CONVERSIONS ARE PRETTY GOOD, MASSIVEOPPORTUNTIY ON ALL PLATOFMRS, ENTIRELY RELIANT ON GOOGLE; JUST STARTED META â€“ MEDIOCRE CREATIVE,AGENCY COMING ON BOARD WITH META CREATIVE (2 ACTUALLY); AGENCY HELPING WITH PAID (MAINLY SEARCH);COULD ALWAYS BE A GOOGLE FIRST SHOP; YOUTUBE â€“ NEED TO CREATE AWARENESS; MONETIZE AN APPOINTMENT;OPEN TO CHATTING; TESTING TIKTOK; TESTING PODCAST; TESTING CTV; LOOKING TO OPEN UP META AND OE OTHERCHANNEL; ROAS IS FINE â€“ SHOULD BE REALLY GOOD; CACS HAVE GONE DOWN A LOT IN TH ELAST YEAR; CREATINGAWARENESS"}]}]},{"type":"listItem","content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"type":"text","marks":[{"type":"bold"}],"text":"USING PMAX, OPTIMIZINGFOR ROAS BUT IGNORING PEOPLE WHO COULDNâ€™T PAY; HUGE OPPORTUNITY TO GET PEOPLE USING THESERVICE"}]}]},{"type":"listItem","content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"type":"text","marks":[{"type":"bold"}],"text":"BEST FUNNEL IS PEOPLE CHATTING; CRM IS MORE ABOUTREPEAT BUSINESS"}]}]}]}]},{"type":"listItem","content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"type":"text","marks":[{"type":"bold"}],"text":"\"What does the funnelactually look like from someone starting an anonymous AI conversation to becoming a patient or repeatuser?\""}]}]},{"type":"listItem","content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"type":"text","marks":[{"type":"bold"}],"text":"\"What''s driving growth today? Organic/search,paid acquisition, partnerships, word of mouth?\""}]}]},{"type":"listItem","content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"type":"text","marks":[{"type":"bold"}],"text":"\"What metric do you ultimately optimize around? Consultations, registeredusers, physician visits, revenue, repeat care, something else?\""}]},{"type":"orderedList","attrs":{"start":1,"type":"1"},"content":[{"type":"listItem","content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"type":"text","marks":[{"type":"bold"}],"text":"SEM IS BIGGEST DRIVERAND SEO IS QUITE ROBUST; FOCUS WAS ON TRAFFIC NOW ON CONVERSION"}]}]},{"type":"listItem","content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"type":"text","marks":[{"type":"bold"}],"text":"DONâ€™T DO GREAT ORGANIC/PAID SEPERATION WELL"}]}]},{"type":"listItem","content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"type":"text","marks":[{"type":"bold"}],"text":"1MM/MONTH â€“ WANT TO HOLD IT FLAT FOR NEXT MONTH+;ROOM FOR EFFICIENCY. MAINLY PMAX; META ADSETS NOT CAMPAIGNS"}]}]}]}]},{"type":"listItem","content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"type":"text","marks":[{"type":"bold"}],"text":"WHAT ABOUT COMPETITORS â€“ SOME ARE VERY SIMILAR, MUCH SMALLER (COUNSELHEALTH, K HEALTH); CHATGPT NOT A DIRECT COMPETTIOR â€“ NOT HIPPA COMPLIANT, NO GUARDLINES; NEED TOCREATE BEHAVIOR CHANGE"}]}]}]},{"type":"paragraph","attrs":{"textAlign":null},"content":[{"type":"text","marks":[{"type":"bold"}],"text":"Â "}]},{"type":"paragraph","attrs":{"textAlign":null},"content":[{"type":"text","marks":[{"type":"bold"}],"text":"WHAT WOULD PARTR TIMERATE BE AND STRUCTURE IT"}]},{"type":"paragraph","attrs":{"textAlign":null},"content":[{"type":"text","marks":[{"type":"bold"}],"text":"CREATIVE STRATEGY â€“ GOOD AT THAT BUT GOING TO SEETHEIR SLICE OF PERFORMANCE; PRODUCT IS FOR EVERYBODY"}]},{"type":"paragraph","attrs":{"textAlign":null},"content":[{"type":"text","marks":[{"type":"bold"}],"text":"15-20 HOURS PER WEEKAND SCALE FROM THERE"}]},{"type":"paragraph","attrs":{"textAlign":null},"content":[{"type":"text","text":"Â "}]},{"type":"orderedList","attrs":{"start":6,"type":"1"},"content":[{"type":"listItem","content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"type":"text","marks":[{"type":"bold"}],"text":"\"How do you think about the relationship betweenthe AI experience and the physician business? Is AI primarily acquisition and triage today, or do youultimately see Doctronic becoming someone''s actual primary-care relationship?\""}]}]},{"type":"listItem","content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"type":"text","marks":[{"type":"bold"}],"text":"\"What does the growth organization look liketoday, and where do you think you''re missing capability?\""}]}]}]},{"type":"paragraph","attrs":{"textAlign":null},"content":[{"type":"text","text":"Â "}]},{"type":"paragraph","attrs":{"textAlign":null},"content":[{"type":"text","text":"Homepage is weak and the chat window looks akinto chatgpt/claude"}]},{"type":"paragraph","attrs":{"textAlign":null},"content":[{"type":"text","text":"How do you differentiate yourself from those â€“ which are free as well andhave some authority/trust"}]},{"type":"paragraph","attrs":{"textAlign":null},"content":[{"type":"text","text":"Collecting email up front"}]},{"type":"paragraph","attrs":{"textAlign":null},"content":[{"type":"text","text":"Â "}]},{"type":"paragraph","attrs":{"textAlign":null},"content":[{"type":"text","text":"Doctronic â€“ been there a month"}]},{"type":"paragraph","attrs":{"textAlign":null},"content":[{"type":"text","text":"Â "}]},{"type":"paragraph","attrs":{"textAlign":null},"content":[{"type":"text","text":"Â "}]}]}','bbef7f13-78dc-4023-8324-f0248fb24e40',0,NULL,3,0,'2026-09-16T19:48:15.187Z','2026-09-16T19:48:05.215Z','2026-09-16T19:48:15.187Z','Doctronic They''re building an AI-first version of primary and urgent care. Youstart with an AI doctor for free, and if you actually need treatment, you''re handed off to alicensed physician who already has the context. $39 for self-pay AI-assisted prescription renewals inUtah Health question â†’ AI conversation â†’ useful answer â†’ trust â†’ account/history â†’physician visit â†’ treatment â†’ repeat use â†’ ongoing primary-care relationship So Doctronic hasto design a very intelligent boundary between free AI utility and monetizable human care whilemaintaining clinical safety and consumer trust. "Most of my career has been in consumer growth andperformance marketing, but there''s been a pretty consistent thread of building acquisition enginesin businesses that are creating new consumer behaviors. I was employee six at Talkspace and helpedscale paid acquisition from about $20,000 a month to $1 million a month when online therapy itselfwas still a new concept. I later ran acquisition at Thriveworks across virtual care and more than 300physical locations, and most recently led growth at Origin across virtual and in-person women''shealthcare. The other piece that''s become increasingly important in how I work is AI. I''ve beenbuilding it into research, analysis, experimentation and marketing workflows pretty aggressively. Sothe combination of consumer healthcare, growth, and an AI-native product is obviously prettyinteresting to me." A consumer healthcare growth operator who knows how to take an emerginghealthcare behavior and turn it into a scalable acquisition and conversion engine. Talkspace:Convince consumers that therapy can happen online. Thriveworks: Scale acquisition across physical +virtual behavioral healthcare. Origin: Scale patient acquisition across physical + virtual women''shealthcare. Doctronic: Convince consumers that the first interaction in healthcare can happen withAI. Questions I would ask them "Where is the business today in terms of growth? Is the biggerchallenge acquiring more users, or converting the enormous amount of AI usage you already have intoongoing patient relationships?" AWARENESS IS LOW, A LOT OF MOMENTUM, CONVERSIONS ARE PRETTY GOOD,MASSIVE OPPORTUNTIY ON ALL PLATOFMRS, ENTIRELY RELIANT ON GOOGLE; JUST STARTED META â€“ MEDIOCRECREATIVE, AGENCY COMING ON BOARD WITH META CREATIVE (2 ACTUALLY); AGENCY HELPING WITH PAID (MAINLYSEARCH); COULD ALWAYS BE A GOOGLE FIRST SHOP; YOUTUBE â€“ NEED TO CREATE AWARENESS; MONETIZE ANAPPOINTMENT; OPEN TO CHATTING; TESTING TIKTOK; TESTING PODCAST; TESTING CTV; LOOKING TO OPEN UP METAAND OE OTHER CHANNEL; ROAS IS FINE â€“ SHOULD BE REALLY GOOD; CACS HAVE GONE DOWN A LOT IN TH ELASTYEAR; CREATING AWARENESS USING PMAX, OPTIMIZING FOR ROAS BUT IGNORING PEOPLE WHO COULDNâ€™T PAY; HUGEOPPORTUNITY TO GET PEOPLE USING THE SERVICE BEST FUNNEL IS PEOPLE CHATTING; CRM IS MORE ABOUT REPEATBUSINESS "What does the funnel actually look like from someone starting an anonymous AI conversationto becoming a patient or repeat user?" "What''s driving growth today? Organic/search, paidacquisition, partnerships, word of mouth?" "What metric do you ultimately optimize around?Consultations, registered users, physician visits, revenue, repeat care, something else?" SEM ISBIGGEST DRIVER AND SEO IS QUITE ROBUST; FOCUS WAS ON TRAFFIC NOW ON CONVERSION DONâ€™T DO GREATORGANIC/PAID SEPERATION WELL 1MM/MONTH â€“ WANT TO HOLD IT FLAT FOR NEXT MONTH+; ROOM FOR EFFICIENCY.MAINLY PMAX; META ADSETS NOT CAMPAIGNS WHAT ABOUT COMPETITORS â€“ SOME ARE VERY SIMILAR, MUCH SMALLER(COUNSEL HEALTH, K HEALTH); CHATGPT NOT A DIRECT COMPETTIOR â€“ NOT HIPPA COMPLIANT, NO GUARDLINES;NEED TO CREATE BEHAVIOR CHANGE WHAT WOULD PARTR TIME RATE BE AND STRUCTURE IT CREATIVE STRATEGY â€“GOOD AT THAT BUT GOING TO SEE THEIR SLICE OF PERFORMANCE; PRODUCT IS FOR EVERYBODY 15-20 HOURS PERWEEK AND SCALE FROM THERE "How do you think about the relationship between the AI experience and thephysician business? Is AI primarily acquisition and triage today, or do you ultimately see Doctronicbecoming someone''s actual primary-care relationship?" "What does the growth organization look liketoday, and where do you think you''re missing capability?" Homepage is weak and the chat window looksakin to chatgpt/claude How do you differentiate yourself from those â€“ which are free as well andhave some authority/trust Collecting email up front Doctronic â€“ been there amonth',0,NULL,NULL,NULL,0);
