INSERT OR IGNORE INTO "entities"("id","type","title","content","parent_id","is_top_level","status","position","pinned","last_touched","created_at","updated_at","search_text","is_jot","due_date","due_time","due_position","is_list")VALUES('39b32262-7940-4557-9a0a-9f0d684b8a4a','note','Unlined Roads','{"type":"doc","content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"type":"text","text":"I had an idea foryou, my wife and I were surprised you didn''t comment on* it yet even lol."}]},{"type":"paragraph","attrs":{"textAlign":null},"content":[{"type":"hardBreak"}]},{"type":"paragraph","attrs":{"textAlign":null},"content":[{"type":"text","text":"Bedford Center Road(near the Bedford Community Church, past 684) was repaved and they still haven''t painted the lines.Also on Springhurst Road. It''s been close to, or more than, 30 days since these have been repavedand they still don''t have the yellow median painted."}]},{"type":"paragraph","attrs":{"textAlign":null},"content":[{"type":"hardBreak"}]},{"type":"paragraph","attrs":{"textAlign":null},"content":[{"type":"text","text":"I thought it would be hilarious if you used abeeÂ rolling on the road to paint the yellow lines"}]}]}','0a4baef4-e8c6-4ac4-9243-6f405878e095',0,NULL,2,0,'2026-09-18T22:31:16.540Z','2026-09-18T22:31:11.579Z','2026-09-18T22:31:16.540Z','I had an idea for you, my wife and I were surprised you didn''t comment on* it yeteven lol. Bedford Center Road (near the Bedford Community Church, past 684) was repaved and theystill haven''t painted the lines. Also on Springhurst Road. It''s been close to, or more than, 30days since these have been repaved and they still don''t have the yellow median painted. I thought itwould be hilarious if you used a bee rolling on the road to paint the yellowlines',0,NULL,NULL,NULL,0);
